'use client';

import { useEffect, useState, useRef } from 'react';
import { useSession, signOut } from 'next-auth/react';
import { useAudioStreaming } from '@/app/hooks/useAudioStreaming';

export default function DashboardClient({ initialData }: { initialData: any }) {
  const { data: session } = useSession();
  const [data, setData] = useState(initialData);
  const [loadingRefresh, setLoadingRefresh] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const wsToken = (session as any)?.wsToken;
  const wsUrl = wsToken ? `ws://localhost:8080?token=${wsToken}` : null;
  const {
    startStreaming,
    stopStreaming,
    isRecording,
    isSpeaking,
    userVolume,
    chatMessages,
    currentUserTranscript,
  } = useAudioStreaming(wsUrl || '');

  const refreshData = async () => {
    setLoadingRefresh(true);
    try {
      const response = await fetch('/api/user');
      if (!response.ok) {
        throw new Error('Failed to fetch user data');
      }
      const newData = await response.json();
      setData(newData);
    } catch (error) {
      console.error('Error refreshing user data:', error);
    } finally {
      setLoadingRefresh(false);
    }
  };

  useEffect(() => {
    if (session?.user?.id && !isRecording && !loadingRefresh) {
      refreshData();
    }
  }, [isRecording, session?.user?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // Scroll to bottom when chat messages update
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({
      behavior: 'smooth',
      block: 'end',
    });
  }, [chatMessages]); // Dependency array includes chatMessages

  const volumeScale = userVolume / 255;

  return (
    <div className="min-h-screen bg-slate-50 p-8">
      <header className="flex justify-between items-center mb-10">
        <div>
          <h1 className="text-3xl font-bold text-slate-900">
            ¡Hola, {data?.name || 'usuario'}!
          </h1>
          <p className="text-slate-500">Revisa tu progreso en tiempo real.</p>
        </div>
        <button
          onClick={() => signOut()}
          className="px-4 py-2 bg-red-500 text-white rounded-lg"
        >
          Cerrar Sesión
        </button>
      </header>

      {/* Chat Display Area */}
      <div className="mb-6 p-4 bg-white rounded-2xl shadow-lg border border-slate-100 h-96 overflow-y-auto flex flex-col-reverse">
        <div className="space-y-4" ref={messagesEndRef}>
          {[...chatMessages].reverse().map((msg, index) => (
            <div
              key={index}
              className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-xs md:max-w-md lg:max-w-lg p-3 rounded-lg ${msg.sender === 'user' ? 'bg-blue-500 text-white' : 'bg-gray-200 text-gray-800'}`}
              >
                {msg.text}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Real-time User Transcript Display */}
      <div className="mb-6 p-4 bg-white rounded-2xl shadow-inner border border-slate-200 min-h-[4rem] flex items-center justify-center">
        <p className="text-slate-600 italic text-center">
          {currentUserTranscript || "Haz clic en 'Empezar a Hablar' para iniciar la conversación."}
        </p>
      </div>

      <div className="mb-6 flex items-center space-x-4 p-4 bg-white rounded-2xl shadow-sm border border-slate-100">
        <div className="relative">
          <button
            onClick={startStreaming}
            disabled={isRecording || !wsUrl}
            className={`relative px-6 py-3 rounded-full text-white font-semibold transition-colors duration-200 overflow-hidden
              ${!wsUrl ? 'bg-gray-400 cursor-not-allowed' : isRecording ? 'bg-red-500' : 'bg-blue-600 hover:bg-blue-700'}`}
          >
            {isRecording ? 'Grabando...' : 'Empezar a Hablar'}
          </button>
          {isRecording && (
            <span
              className="absolute inset-0 bg-blue-400 opacity-50 rounded-full transition-all duration-75 ease-out"
              style={{ transform: `scale(${1 + volumeScale * 0.5})` }}
            ></span>
          )}
        </div>
        <button
          onClick={stopStreaming}
          disabled={!isRecording}
          className={`px-6 py-3 rounded-full text-white font-semibold transition-colors duration-200
            ${!isRecording ? 'bg-gray-400 cursor-not-allowed' : 'bg-red-600 hover:bg-red-700'}`}
        >
          Detener Grabación
        </button>
        <span className="text-sm text-slate-600">
          Estado:
          {isRecording && (
            <span className="text-red-500 font-medium ml-1">Grabando</span>
          )}
          {isSpeaking && (
            <span className="text-blue-500 font-medium ml-1 animate-pulse">IA Hablando</span>
          )}
          {!isRecording && !isSpeaking && (
            <span className="text-gray-500 font-medium ml-1">Inactivo</span>
          )}
          {loadingRefresh && (
            <span className="text-purple-500 font-medium ml-1">
              Actualizando...
            </span>
          )}
        </span>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-sm font-semibold text-slate-400 uppercase">
            Nivel Actual
          </h3>
          <p className="text-4xl font-black text-blue-600 mt-2">
            {data?.languageLevel || 'N/A'}
          </p>
        </div>
        <div className="md:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-sm font-semibold text-slate-400 uppercase mb-4">
            Habilidades Desbloqueadas
          </h3>
          <div className="flex flex-wrap gap-2">
            {data?.analytics?.masteredTopics.map((topic: string) => (
              <span
                key={topic}
                className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-sm font-medium"
              >
                ✓ {topic}
              </span>
            )) || (
              <span className="text-slate-500 text-sm">
                No hay temas dominados aún.
              </span>
            )}
          </div>
        </div>
        <div className="md:col-span-3 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-sm font-semibold text-slate-400 uppercase mb-4">
            Notas del Tutor IA
          </h3>
          <div className="space-y-4">
            {data?.lessons.map((lesson: any) => (
              <div
                key={lesson.id}
                className="border-l-4 border-blue-500 pl-4 py-2"
              >
                <p className="text-slate-700 font-medium">{lesson.topic}</p>
                <p className="text-slate-500 text-sm italic">
                  "{lesson.feedback}"
                </p>
              </div>
            )) || (
              <span className="text-slate-500 text-sm">
                No hay feedback reciente.
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
