'use client';

import { useEffect, useRef, useState, useCallback } from 'react';

interface ChatMessage {
  sender: 'user' | 'ai';
  text: string;
}

type ServerMessage =
  | { type: 'user_interim'; text: string }
  | { type: 'user_final'; text: string }
  | { type: 'ai_delta'; delta: string }
  | { type: 'ai_final' }
  | { type: 'error'; message: string };

export const useAudioStreaming = (url: string | null) => {
  /* ===============================
     ESTADOS
  =============================== */

  const [isRecording, setIsRecording] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false); // IA hablando
  const [userVolume, setUserVolume] = useState(0);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [currentUserTranscript, setCurrentUserTranscript] = useState('');

  /* ===============================
     REFERENCIAS INTERNAS
  =============================== */

  const socketRef = useRef<WebSocket | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const sourceNodeRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const animationFrameRef = useRef<number | null>(null);

  // Control de turnos
  const isUserTurnRef = useRef(true);

  /* ===============================
     AUDIO CONTEXT
  =============================== */

  const getAudioContext = useCallback(() => {
    if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
      audioContextRef.current = new (window.AudioContext ||
        (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  }, []);

  /* ===============================
     MEDICIÓN DE VOLUMEN
  =============================== */

  const measureVolume = useCallback(() => {
    if (!analyserRef.current) return;

    const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
    analyserRef.current.getByteFrequencyData(dataArray);

    const average =
      dataArray.reduce((acc, val) => acc + val, 0) / dataArray.length;

    setUserVolume(average);

    animationFrameRef.current = requestAnimationFrame(measureVolume);
  }, []);

  /* ===============================
     INICIAR STREAMING
  =============================== */

  const startStreaming = useCallback(async () => {
    if (!url || isRecording) return;

    setChatMessages([]);
    setCurrentUserTranscript('Conectando...');
    isUserTurnRef.current = true;

    const ws = new WebSocket(url);
    socketRef.current = ws;

    ws.onopen = async () => {
      setCurrentUserTranscript('Habla cuando quieras...');
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const audioContext = getAudioContext();
      if (audioContext.state === 'suspended') {
        await audioContext.resume();
      }

      // Crear nodos de audio
      sourceNodeRef.current = audioContext.createMediaStreamSource(stream);
      analyserRef.current = audioContext.createAnalyser();
      analyserRef.current.fftSize = 256;

      sourceNodeRef.current.connect(analyserRef.current);

      // MediaRecorder envía chunks cada 250ms
      mediaRecorderRef.current = new MediaRecorder(stream, {
        mimeType: 'audio/webm',
      });

      mediaRecorderRef.current.ondataavailable = (event) => {
        // Solo enviar si:
        // - hay datos
        // - WebSocket abierto
        // - es turno del usuario
        if (
          event.data.size > 0 &&
          ws.readyState === WebSocket.OPEN &&
          isUserTurnRef.current
        ) {
          ws.send(event.data);
        }
      };

      mediaRecorderRef.current.start(250);

      setIsRecording(true);
      animationFrameRef.current = requestAnimationFrame(measureVolume);
    };

    /* ===============================
       MENSAJES DEL SERVIDOR
    =============================== */

    ws.onmessage = (event) => {
      const data: ServerMessage = JSON.parse(event.data);

      switch (data.type) {
        case 'user_interim':
          // Transcripción parcial
          setCurrentUserTranscript(data.text + '...');
          break;

        case 'user_final':
          // Transcripción final del usuario
          setCurrentUserTranscript(data.text);
          setChatMessages((prev) => [
            ...prev,
            { sender: 'user', text: data.text },
          ]);

          // Cambiamos turno → ahora habla la IA
          isUserTurnRef.current = false;
          setIsSpeaking(true);
          break;

        case 'ai_delta':
          // Streaming token-by-token
          setChatMessages((prev) => {
            const last = prev[prev.length - 1];

            if (last && last.sender === 'ai') {
              const updated = [...prev];
              updated[updated.length - 1] = {
                sender: 'ai',
                text: last.text + data.delta, // acumulación real
              };
              return updated;
            }

            return [...prev, { sender: 'ai', text: data.delta }];
          });
          break;

        case 'ai_final':
          // La IA terminó de responder
          setIsSpeaking(false);
          isUserTurnRef.current = true;
          setCurrentUserTranscript('Tu turno...');
          break;

        case 'error':
          setCurrentUserTranscript(`Error: ${data.message}`);
          break;
      }
    };

    ws.onerror = () => {
      setCurrentUserTranscript('Error de conexión');
    };

    ws.onclose = () => {
      cleanup();
    };
  }, [url, isRecording, getAudioContext, measureVolume]);

  /* ===============================
     DETENER STREAMING
  =============================== */

  const stopStreaming = useCallback(() => {
    cleanup();
  }, []);

  /* ===============================
     LIMPIEZA CENTRALIZADA
  =============================== */

  const cleanup = () => {
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }

    mediaRecorderRef.current?.stop();

    sourceNodeRef.current?.mediaStream
      .getTracks()
      .forEach((track) => track.stop());

    if (socketRef.current?.readyState === WebSocket.OPEN) {
      socketRef.current.close();
    }

    setIsRecording(false);
    setIsSpeaking(false);
    setUserVolume(0);
  };

  /* ===============================
     CLEANUP AL DESMONTAR
  =============================== */

  useEffect(() => {
    return () => {
      cleanup();
    };
  }, []);

  /* ===============================
     RETURN
  =============================== */

  return {
    startStreaming,
    stopStreaming,
    isRecording,
    isSpeaking,
    userVolume,
    chatMessages,
    currentUserTranscript,
  };
};
